from collections import defaultdict, deque

class Solution:
    def treeDiameter(self, edges: list[list[int]]) -> int:
        if not edges:
            return 0

        # Build the adjacency list
        graph = defaultdict(list)
        for u, v in edges:
            graph[u].append(v)
            graph[v].append(u)

        def bfs(start):
            visited = {start}
            queue = deque([(start, 0)])
            farthest = (start, 0)
            while queue:
                node, depth = queue.popleft()
                if depth > farthest[1]:
                    farthest = (node, depth)
                for neighbor in graph[node]:
                    if neighbor not in visited:
                        visited.add(neighbor)
                        queue.append((neighbor, depth + 1))
            return farthest

        # First BFS from any node (e.g., node in first edge) finds one end of a longest path
        x, _ = bfs(edges[0][0])
        # Second BFS from x gives the diameter (in edges)
        y, diameter = bfs(x)
        return diameter
